<?php
session_start(); require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../includes/audit.php'; require_once __DIR__ . '/../includes/consent.php'; requireRole('doctor');
$doctorQuery = $pdo->prepare('SELECT id FROM doctors WHERE user_id = :user_id LIMIT 1'); $doctorQuery->execute([':user_id' => $_SESSION['user_id']]); $doctorId = $doctorQuery->fetchColumn(); if (!$doctorId) { http_response_code(403); exit('Doctor profile not found.'); }
$patients = $pdo->query("SELECT p.id, i.full_name, i.demo_health_id FROM patients p JOIN demo_health_identities i ON i.id = p.health_identity_id WHERE i.verification_status = 'verified' ORDER BY i.full_name")->fetchAll(PDO::FETCH_ASSOC);
if ($_SERVER['REQUEST_METHOD'] === 'POST') { $patientId = filter_input(INPUT_POST, 'patient_id', FILTER_VALIDATE_INT); $purpose = trim($_POST['purpose'] ?? ''); $requestedData = trim($_POST['requested_data'] ?? ''); $expiresAt = $_POST['expires_at'] ?? ''; if (!verifyCsrfToken($_POST['csrf_token'] ?? null) || !$patientId || $purpose === '' || $requestedData === '') { flash('danger', 'Complete all consent request fields.'); } elseif ($expiresAt !== '' && strtotime($expiresAt) <= time()) { flash('danger', 'Expiry must be in the future.'); } else { $patientCheck = $pdo->prepare("SELECT p.id FROM patients p JOIN demo_health_identities i ON i.id = p.health_identity_id WHERE p.id = :patient_id AND i.verification_status = 'verified' LIMIT 1"); $patientCheck->execute([':patient_id' => $patientId]); if (!$patientCheck->fetchColumn()) { flash('danger', 'Verified patient not found.'); } else { $insert = $pdo->prepare("INSERT INTO consent_requests (patient_id, requested_by, purpose, requested_data, status, expires_at) VALUES (:patient_id, :requested_by, :purpose, :requested_data, 'pending', :expires_at)"); $insert->execute([':patient_id' => $patientId, ':requested_by' => $_SESSION['user_id'], ':purpose' => $purpose, ':requested_data' => $requestedData, ':expires_at' => $expiresAt !== '' ? date('Y-m-d H:i:s', strtotime($expiresAt)) : null]); $requestId = (int) $pdo->lastInsertId(); $notification = $pdo->prepare("INSERT INTO notifications (user_id, title, message) SELECT p.user_id, 'Consent request received', :message FROM patients p WHERE p.id = :patient_id"); $notification->execute([':message' => 'A doctor requested access to: ' . $requestedData, ':patient_id' => $patientId]); logAudit('CONSENT_REQUESTED', 'consent_request', $requestId, 'Doctor requested patient consent.'); flash('success', 'Consent request sent to the patient.'); redirect('request_consent.php'); } } }
$pageTitle = 'Request Consent'; require __DIR__ . '/../includes/header.php';
?><div class="setup-shell"><div class="setup-card"><p class="eyebrow">Privacy workflow</p><h1 class="h3">Request Patient Consent</h1><p class="text-muted">The patient must approve access before protected medical data is displayed.</p><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrfToken()) ?>"><label class="form-label">Patient</label><select class="form-select mb-3" name="patient_id" required><option value="">Select patient</option><?php foreach ($patients as $patient): ?><option value="<?= (int) $patient['id'] ?>"><?= e($patient['full_name'] . ' - ' . $patient['demo_health_id']) ?></option><?php endforeach; ?></select><label class="form-label">Purpose</label><input class="form-control mb-3" name="purpose" placeholder="Continuity of care" required><label class="form-label">Requested data</label><textarea class="form-control mb-3" name="requested_data" rows="3" placeholder="Medical records and prescriptions" required></textarea><label class="form-label">Expiry date and time <span class="text-muted">(optional)</span></label><input class="form-control mb-3" type="datetime-local" name="expires_at"><button class="btn btn-primary">Send consent request</button></form></div></div><?php require __DIR__ . '/../includes/footer.php'; ?>